bodyText:
So I am currently working on this issue (#4431) using this as a template. I got it up and running and everything worked like it was supposed to.
I then tried to use the Lambda beta 04 instead of beta 01 that is used in the example. Using that makes the searcher lambda throw this error:
INFO searcher request: quickwit_lambda::searcher::api: new request method="POST" route="/" request_id="3790f8ef-2edb-44f5-89b0-fbe041a790b7"

ERROR searcher request: quickwit_lambda::searcher::api: request rejected rejection=Rejection(NotFound) request_id="3790f8ef-2edb-44f5-89b0-fbe041a790b7"

INFO searcher request: quickwit_lambda::searcher::api: request completed status="404" request_id="3790f8ef-2edb-44f5-89b0-fbe041a790b7"

I tried to add route, which would use the search route, to the input payload like the following (I remade the test CLI in go):
payload, err := json.Marshal(map[string]interface{}{
		"headers": map[string]string{
			"Content-Type": "application/json",
		},
		"requestContext": map[string]interface{}{
			"http": map[string]string{
				"method": "POST",
				"route":  "/api/v1/hdfs-logs/search",
			},
		},
		"body":            jsonQuery,
		"isBase64Encoded": false,
	})

In the logs the route is still set as route="/"
Does anybody know how to make the lambda beta 04 work?

This is my otel-collector config:
---
receivers:
  otlp:
    protocols:
      grpc:
        endpoint: 0.0.0.0:4317
      http:
        endpoint: 0.0.0.0:4318

processors:
  batch:

  attributes/dev:
    actions:
      - key: deployment.environment
        value: development
        action: insert

exporters:
  otlp/quickwit:
    endpoint: 10.10.0.83:7281
    tls:
      insecure: true

service:
  pipelines:
    logs:
      receivers:
        - otlp
      processors:
        - batch
      exporters:
        - otlp/quickwit

    traces:
      receivers:
        - otlp
      processors:
        - batch
        - attributes/dev
      exporters:
        - otlp/quickwit

in the otel-collector I see this error:
warn        otlpexporter@v0.107.0/otlp.go:126        Partial success response        {"kind": "exporter", "data_type": "logs", "name": "otlp/quickwit", "message": "", "dropped_log_records": 10}

In quickwit I get this error:
ERROR ingest_logs:parse_logs: quickwit_opentelemetry::otlp::logs: skipping record

If I try to send logs via HTTP Instead of dropped_log_records being 10 is 2, this is the code I am using:
use anyhow::Result;
use opentelemetry::{global, trace::TracerProvider, KeyValue};
use opentelemetry_appender_tracing::layer;
use opentelemetry_otlp::WithExportConfig;
use opentelemetry_sdk::{runtime::Tokio, trace::Config, Resource};
use std::time::Duration;
use tracing_opentelemetry::OpenTelemetryLayer;
use tracing_subscriber::{fmt, layer::SubscriberExt, EnvFilter, Registry};

/// Start the telemetry layer
/// # Errors
/// Will return an error if the telemetry layer fails to start
pub fn init(verbosity_level: tracing::Level) -> Result<()> {
    let tracer_provider = opentelemetry_otlp::new_pipeline()
        .tracing()
        .with_exporter(
            opentelemetry_otlp::new_exporter()
                .tonic()
                .with_timeout(Duration::from_secs(3)),
        )
        .with_trace_config(Config::default().with_resource(Resource::new(vec![
            KeyValue::new("service.name", env!("CARGO_PKG_NAME")),
            KeyValue::new("service.version", env!("CARGO_PKG_VERSION")),
        ])))
        .install_batch(Tokio)?;

    let tracer = tracer_provider
        .tracer_builder(env!("CARGO_PKG_NAME"))
        .with_version(env!("CARGO_PKG_VERSION"))
        .build();

    global::set_tracer_provider(tracer_provider);

    let otel_trace_layer = OpenTelemetryLayer::new(tracer);

    let logger = opentelemetry_otlp::new_pipeline()
        .logging()
        .with_resource(Resource::new(vec![KeyValue::new(
            env!("CARGO_PKG_NAME"),
            env!("CARGO_PKG_VERSION"),
        )]))
        .with_exporter(opentelemetry_otlp::new_exporter().tonic())
        .install_batch(Tokio)?;

    let otel_logs_layer = layer::OpenTelemetryTracingBridge::new(&logger);

    let fmt_layer = fmt::layer()
        .with_file(true)
        .with_line_number(true)
        .with_thread_ids(false)
        .with_thread_names(false)
        .with_target(false)
        .json();

    // RUST_LOG=
    let env_filter = EnvFilter::builder()
        .with_default_directive(verbosity_level.into())
        .from_env_lossy();

    let subscriber = Registry::default()
        .with(fmt_layer)
        .with(otel_trace_layer)
        .with(otel_logs_layer)
        .with(env_filter);

    Ok(tracing::subscriber::set_global_default(subscriber)?)
}
Any idea of what could it be wrong ?
